import{_ as a,o as e,c as d,a3 as r}from"./chunks/framework.BlfGB29P.js";const b=JSON.parse('{"title":"UI 框架选型","description":"","frontmatter":{"title":"UI 框架选型","outline":[2,3],"article":{"type":"decision","structure":"decision"}},"headers":[],"relativePath":"frontend/decisions/tooling/framework-selection.md","filePath":"frontend/decisions/tooling/framework-selection.md","lastUpdated":1785589115000}'),i={name:"frontend/decisions/tooling/framework-selection.md"};function o(l,t,h,n,c,u){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="ui-框架选型" tabindex="-1">UI 框架选型 <a class="header-anchor" href="#ui-框架选型" aria-label="Permalink to &quot;UI 框架选型&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>UI 框架选型不是比较谁的 API 更优雅，而是确认候选是否覆盖产品交互、团队能力、生态集成和三至五年的维护责任。React 19、Vue 3 等成熟框架通常都能实现常规 Web 应用，真正拉开差异的是当前场景中的组织和资产约束。</p><h2 id="_1-决策背景" tabindex="-1">1. 决策背景 <a class="header-anchor" href="#_1-决策背景" aria-label="Permalink to &quot;1. 决策背景&quot;">​</a></h2><p>框架会进入组件模型、状态更新、测试、路由、服务端渲染、招聘和组件资产，退出成本高于普通库。新项目需要选择，旧项目则应先证明更换框架产生的收益高于双轨和迁移成本。</p><p>本章不重复 React 或 Vue 的基础 API；可先阅读<a href="/frontend/guide/core/react/">React 19</a>和<a href="/frontend/guide/core/vue/">Vue 3</a>了解各自能力。</p><h2 id="_2-硬约束与评价标准" tabindex="-1">2. 硬约束与评价标准 <a class="header-anchor" href="#_2-硬约束与评价标准" aria-label="Permalink to &quot;2. 硬约束与评价标准&quot;">​</a></h2><h3 id="_2-1-硬约束" tabindex="-1">2.1 硬约束 <a class="header-anchor" href="#_2-1-硬约束" aria-label="Permalink to &quot;2.1 硬约束&quot;">​</a></h3><ul><li>支持公司的浏览器、设备和无障碍基线；</li><li>核心框架及关键生态许可证符合分发方式；</li><li>安全维护和版本生命周期覆盖项目计划；</li><li>能与既有身份、监控、设计系统、测试和部署环境集成；</li><li>关键交互经过原型验证，没有依赖未承诺的实验性能力。</li></ul><h3 id="_2-2-评价维度" tabindex="-1">2.2 评价维度 <a class="header-anchor" href="#_2-2-评价维度" aria-label="Permalink to &quot;2.2 评价维度&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>应收集的证据</th></tr></thead><tbody><tr><td>产品适配</td><td>复杂表单、表格、编辑器、SSR 等关键旅程原型</td></tr><tr><td>团队能力</td><td>能独立设计、评审和排障的人数</td></tr><tr><td>既有资产</td><td>可直接复用的组件、工具、规范和测试比例</td></tr><tr><td>生态健康</td><td>官方维护、关键集成版本节奏、替代供应者</td></tr><tr><td>运行质量</td><td>真实原型的脚本、交互、内存和错误边界</td></tr><tr><td>长期成本</td><td>升级、招聘、培训、跨框架协作和退出成本</td></tr></tbody></table><p>下载量、明星数和网络争论可以用于发现候选，不能替代这些证据。</p><h2 id="_3-候选方案" tabindex="-1">3. 候选方案 <a class="header-anchor" href="#_3-候选方案" aria-label="Permalink to &quot;3. 候选方案&quot;">​</a></h2><h3 id="_3-1-不使用通用-ui-框架" tabindex="-1">3.1 不使用通用 UI 框架 <a class="header-anchor" href="#_3-1-不使用通用-ui-框架" aria-label="Permalink to &quot;3.1 不使用通用 UI 框架&quot;">​</a></h3><p>静态内容、独立 Web Component 或极小嵌入控件可能只需要标准 Web API。它能减少运行时和框架锁定，但复杂状态、组合和团队约定需要自行建立。</p><h3 id="_3-2-vue-3" tabindex="-1">3.2 Vue 3 <a class="header-anchor" href="#_3-2-vue-3" aria-label="Permalink to &quot;3.2 Vue 3&quot;">​</a></h3><p>Vue 3 提供 SFC、响应式系统和渐进式采用路径，适合已有 Vue 能力和模板型协作的团队。需要评估所选组件生态、状态方案和元框架，而不是把所有第三方能力都归于 Vue 本身。</p><h3 id="_3-3-react-19" tabindex="-1">3.3 React 19 <a class="header-anchor" href="#_3-3-react-19" aria-label="Permalink to &quot;3.3 React 19&quot;">​</a></h3><p>React 19 以组件、Hooks 和广泛生态为核心，适合已有 React 平台、跨端共享或依赖其元框架能力的组织。React 只负责 UI 模型，路由、数据和工程组合仍需单独决策。</p><h3 id="_3-4-其他框架或编译型方案" tabindex="-1">3.4 其他框架或编译型方案 <a class="header-anchor" href="#_3-4-其他框架或编译型方案" aria-label="Permalink to &quot;3.4 其他框架或编译型方案&quot;">​</a></h3><p>Svelte、Solid 等方案可能在模型、体积或开发体验上有优势，但应以关键场景原型、生态依赖、人才和维护计划评估。不能因社区较小直接淘汰，也不能因概念新颖跳过生产证据。</p><h2 id="_4-关键维度对比" tabindex="-1">4. 关键维度对比 <a class="header-anchor" href="#_4-关键维度对比" aria-label="Permalink to &quot;4. 关键维度对比&quot;">​</a></h2><p>案例是 12 人团队的新 B2B 运营平台，需求集中在复杂表单、表格、权限和图表；10 人有 Vue 3 生产经验，2 人有 React 经验；公司已有通过无障碍验收的 Vue 组件库。</p><table tabindex="0"><thead><tr><th>维度</th><th>Vue 3</th><th>React 19</th><th>无通用框架</th></tr></thead><tbody><tr><td>首期能力</td><td>现有团队和组件直接覆盖</td><td>需培训并替换组件</td><td>需自建组合与状态约定</td></tr><tr><td>关键原型</td><td>18 项全部通过</td><td>18 项全部通过</td><td>表单和表格集成成本高</td></tr><tr><td>团队排障</td><td>10 人可独立处理</td><td>2 人可独立处理</td><td>Web 基础能力够，但缺统一模型</td></tr><tr><td>长期资产</td><td>与现有平台一致</td><td>可能扩大跨团队统一</td><td>框架锁定低，内部维护高</td></tr><tr><td>退出策略</td><td>领域层可保持纯 TS</td><td>领域层可保持纯 TS</td><td>组件标准需自行维护</td></tr></tbody></table><p>两种成熟框架都满足产品能力，结论主要由团队和资产决定。</p><h2 id="_5-场景化推荐结论" tabindex="-1">5. 场景化推荐结论 <a class="header-anchor" href="#_5-场景化推荐结论" aria-label="Permalink to &quot;5. 场景化推荐结论&quot;">​</a></h2><p>本案例选择 Vue 3，范围只覆盖新运营平台，不发起其他 React 产品迁移。使用现有设计系统和监控适配，领域模型、请求客户端和校验规则保持纯 TypeScript，降低长期锁定。</p><p>若项目是由现有 React 平台团队维护、需要直接复用 React Native 领域组件或指定 React 元框架，结论可能反转。若只是官网中的一个价格计算器，则可能不需要通用框架。</p><h2 id="_6-引入后的后果" tabindex="-1">6. 引入后的后果 <a class="header-anchor" href="#_6-引入后的后果" aria-label="Permalink to &quot;6. 引入后的后果&quot;">​</a></h2><p>团队获得一致能力和较短交付周期，同时承担 Vue 版本升级、核心生态维护和招聘能力。选择框架后仍需决定路由、状态、数据请求、测试和渲染策略，框架名称不能替代应用架构。</p><p>退出成本主要集中在组件和框架专属状态。通过 Web 契约、纯函数领域层、设计令牌和端到端测试保留迁移空间，但不应为假想迁移抽象每个 API。</p><h2 id="_7-不适用场景" tabindex="-1">7. 不适用场景 <a class="header-anchor" href="#_7-不适用场景" aria-label="Permalink to &quot;7. 不适用场景&quot;">​</a></h2><ul><li>旧系统稳定且迁移没有业务目标时，不要仅因新版本更流行更换框架。</li><li>不要用简单计数的性能基准代表真实页面。</li><li>不要把招聘市场规模当作团队可以立即生产交付的证据。</li><li>不要同时引入框架、状态库、元框架和组件库后，把成败全部归因于 UI 框架。</li><li>微型嵌入组件应先评估标准 Web API 或 Web Component。</li></ul><h2 id="_8-填写完成的决策记录" tabindex="-1">8. 填写完成的决策记录 <a class="header-anchor" href="#_8-填写完成的决策记录" aria-label="Permalink to &quot;8. 填写完成的决策记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>问题</td><td>新 B2B 运营平台使用何种 UI 模型</td></tr><tr><td>硬约束</td><td>12 周首期；无障碍 AA；支持现有浏览器；接入公司监控和权限</td></tr><tr><td>候选</td><td>Vue 3、React 19、标准 Web API</td></tr><tr><td>决定</td><td>Vue 3，仅覆盖新运营平台</td></tr><tr><td>证据</td><td>团队技能盘点、18 项原型、现有组件覆盖率 82%</td></tr><tr><td>接受代价</td><td>继续维护 Vue 技能和生态；跨 React 产品不共享组件实现</td></tr><tr><td>退出路径</td><td>领域层纯 TypeScript；组件通过设计令牌和业务契约协作</td></tr><tr><td>明确不做</td><td>不迁移其他稳定产品；不创建跨框架组件抽象层</td></tr></tbody></table><h2 id="_9-复查条件" tabindex="-1">9. 复查条件 <a class="header-anchor" href="#_9-复查条件" aria-label="Permalink to &quot;9. 复查条件&quot;">​</a></h2><p>关键生态停止维护、熟练维护者低于三人、核心交互连续无法满足性能或无障碍门槛、跨产品共享成为主要业务约束，或年度升级投入连续两次超出预算时复查。框架出现新特性但现有约束未变，不是自动重选的理由。</p>',37)])])}const p=a(i,[["render",o]]);export{b as __pageData,p as default};
